"""Build a fixed-snapshot dashboard dataset; standard library only, no network.

--check rebuilds in memory and checks the committed generated bytes as well as
the supplied manuscript aggregate tables. It never overwrites stale outputs.
"""
import argparse
import csv
import hashlib
import json
from collections import Counter, defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
EXCLUDED = {'GS030', 'GS034', 'GS035', 'GS036', 'GS043', 'GS045', 'GS044'}

def read(path):
    with path.open(encoding='utf-8-sig', newline='') as stream:
        return list(csv.DictReader(stream))

def normalize_doi(value):
    value = value.strip().lower()
    for prefix in ('https://doi.org/', 'http://dx.doi.org/', 'doi:'):
        if value.startswith(prefix):
            value = value[len(prefix):]
    return value.rstrip('.')

def values(value):
    return sorted({x.strip() for x in value.split('|') if x.strip() and x.strip() != 'nan'})

def build():
    source = ROOT / 'data/source'
    registry = read(source / 'seed_registry.csv')
    eligible = {r['seed_id'] for r in registry} - EXCLUDED
    assert len(eligible) == 49
    categories = {r['seed_id']: r['primary_category'] for r in read(source / 'seed_classification_final.csv')}
    edges = [r for r in read(source / 'seed_citation_edges.csv') if r['seed_id'] in eligible]
    seeds = defaultdict(set)
    for r in edges:
        key = normalize_doi(r['citing_doi']) or r['citing_work_id'].strip().lower()
        seeds[key].add(r['seed_id'])
    works = []
    for r in read(source / 'october_master.csv'):
        key = r['dedupe_key'].strip().lower()
        if key not in seeds:
            continue
        year = int(float(r['publication_year'])) if r['publication_year'].strip() else None
        works.append(dict(key=key, title=r['display_name'], year=year,
                          doi=normalize_doi(r['doi']), url=r['id'], type=r['type'],
                          field=r['primary_topic.field'] or 'Unclassified',
                          countries=values(r['authorships.countries']),
                          institutions=values(r['authorships.institutions.id']),
                          categories=sorted({categories[s] for s in seeds[key]})))
    works.sort(key=lambda r: r['key'])
    assert len(works) == 14475, len(works)
    assert len({r['key'] for r in works}) == len(works)
    assert {r['key'] for r in works} == set(seeds), 'Unmatched citation keys'
    unique_edges = {(r['seed_id'], normalize_doi(r['citing_doi']) or r['citing_work_id'].strip().lower()) for r in edges}
    assert len(unique_edges) == 18424, len(unique_edges)
    # Independently reproduce the four supplied full-corpus aggregate tables.
    ref = ROOT / 'data/reference'
    year_counts = Counter(r['year'] for r in works)
    expected_years = {int(r['year']): int(r['publications']) for r in read(ref / 'results_temporal.csv')}
    assert all(year_counts[y] == n for y, n in expected_years.items())
    outside_temporal = sum(n for year, n in year_counts.items() if year not in expected_years)
    assert sum(expected_years.values()) + outside_temporal == len(works)
    for column, filename, reference_key in [
        ('countries', 'results_geographic.csv', 'country'),
        ('institutions', 'results_institutional.csv', 'institution_id')]:
        counts = Counter(v for r in works for v in r[column])
        expected = {r[reference_key]: int(r['publications']) for r in read(ref / filename)}
        assert dict(counts) == expected, filename
    fields = Counter(r['field'] for r in works if r['field'] != 'Unclassified')
    assert dict(fields) == {r['field']: int(r['publications']) for r in read(ref / 'results_disciplinary.csv')}
    # Use the supplied institutional display labels without inferring positional
    # author-institution associations from flattened metadata.
    institutions = {r['institution_id']: r['institution'] or r['institution_id'] for r in read(ref / 'results_institutional.csv')}
    # Validate the original manuscript population above, then apply the explicit
    # dashboard exclusion requested on 2026-10-20. Keep unknown years visible.
    excluded = [r for r in works if r['year'] is not None and r['year'] <= 2005]
    assert len(excluded) == 6
    works = [r for r in works if r not in excluded]
    retained_keys = {r['key'] for r in works}
    retained_edges = {(seed, key) for seed, key in unique_edges if key in retained_keys}
    location_file = ROOT / 'data/institutions/locations.json'
    locations = json.loads(location_file.read_text()) if location_file.exists() else {'institutions': []}
    manifest = dict(definition='D49_approved_dashboard_2006plus', cutoff='2026-10-16', publications=len(works),
                    citation_relationships=len(retained_edges), source_edge_rows=len(edges),
                    original_publications=14475, original_citation_relationships=len(unique_edges),
                    exclusions=[dict(key=r['key'], title=r['title'], year=r['year'],
                                     reason='Publication dated before 2006; dashboard exclusion requested 2026-10-20') for r in excluded],
                    missing_years=sum(r['year'] is None for r in works),
                    duplicate_edge_rows=len(edges)-len(unique_edges),
                    eligible_seeds=len(eligible),
                    excluded_seeds=sorted(EXCLUDED), inputs={})
    for folder in (source, ref):
        for p in sorted(folder.glob('*.csv')):
            manifest['inputs'][str(p.relative_to(ROOT))] = hashlib.sha256(p.read_bytes()).hexdigest()
    if location_file.exists():
        manifest['inputs'][str(location_file.relative_to(ROOT))] = hashlib.sha256(location_file.read_bytes()).hexdigest()
    payload = dict(manifest=manifest, works=works, institutions=institutions, institution_locations=locations['institutions'])
    return (json.dumps(payload, ensure_ascii=False, separators=(',', ':'), sort_keys=True)+'\n').encode()

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    payload = build()
    target = ROOT / 'src/data/corpus.json'
    if args.check:
        assert target.read_bytes() == payload, 'Generated dataset is stale; run npm run data'
    else:
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(payload)
    manifest = json.loads(payload)['manifest']
    print(f"PASS: original four aggregate tables reconcile; {manifest['publications']:,} retained publications; "
          f"{manifest['citation_relationships']:,} retained edges; six dated exclusions; deterministic output.")
